import six
import logging
from abc import ABCMeta, abstractmethod
from taf.ue.plugin.mtk.config import Configuration
from taf.ue.plugin.mtk.commands.at_command import CGDCONT, CGACT, EAPNACT
from taf.ue.plugin.mtk.flow.action_verifiable import ActionSequenceVerifiable
from taf.ue.plugin.mtk.flow.context_alias_store import ContextAliasStore
from taf.ue.plugin.mtk.flow.aid_store import AIDStore
from taf.ue.plugin.mtk.exceptions import ContextIdHasBeenReserved


@six.add_metaclass(ABCMeta)
class PDN(ActionSequenceVerifiable):

    @abstractmethod
    def __init__(self, executor=None, config=None, verifier=None):
        self._executor = executor
        self._config = config
        self._verifier = verifier
        self._pdn_name = ""

    def execute(self, timeout=None, interval=1, pdn_name=""):
        self._pdn_name = pdn_name
        super(PDN, self).execute(timeout, interval)

    def _generate_command_sequence(self):
        apn_url = Configuration().get_apn(self._pdn_name)
        pdp_type = Configuration().get_pdp_type(self._pdn_name)
        try:
            cid = ContextAliasStore().create_context_id(self._pdn_name)
        except ContextIdHasBeenReserved as e:
            logging.debug('{}, use it directly'.format(e))
            cid = ContextAliasStore().get_context_id(self._pdn_name)
        return [CGDCONT(self._executor, cid, pdp_type, apn_url),
                CGACT(self._executor, CGACT.State.ACTIVATED, cid)]

    def verify(self):
        if self._verifier:
            self._verifier.verify()


class NSAPDN(PDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(NSAPDN, self).__init__(executor=executor, config=config, verifier=verifier)


class SAPDN(PDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(SAPDN, self).__init__(executor=executor, config=config, verifier=verifier)


class LTEPDN(PDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(LTEPDN, self).__init__(executor=executor, config=config, verifier=verifier)


class PetrusSAPDN(PDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(PetrusSAPDN, self).__init__(executor=executor, config=config, verifier=verifier)

    def _generate_command_sequence(self):
        apn_url = Configuration().get_apn(self._pdn_name)
        return [EAPNACT(self._executor, EAPNACT.PDPContextActivation.ACTIVATED, apn_url, "default", 0)]


class PetrusNSAPDN(PDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(PetrusNSAPDN, self).__init__(executor=executor, config=config, verifier=verifier)

    def _generate_command_sequence(self):
        return []


@six.add_metaclass(ABCMeta)
class DeactivateAdditionalPDN(ActionSequenceVerifiable):

    @abstractmethod
    def __init__(self, executor=None, config=None, verifier=None):
        self._executor = executor
        self._config = config
        self._verifier = verifier
        self._pdn_name = ""

    def execute(self, timeout=None, interval=1, pdn_name=""):
        self._pdn_name = pdn_name
        super(DeactivateAdditionalPDN, self).execute(timeout, interval)

    def _generate_command_sequence(self):
        cid = ContextAliasStore().release_context_id(self._pdn_name)
        return [CGACT(self._executor, CGACT.State.DEACTIVATED, cid)]

    def verify(self):
        if self._verifier:
            self._verifier.verify()


class NSADeactivateAdditionalPDN(DeactivateAdditionalPDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(NSADeactivateAdditionalPDN, self).__init__(executor=executor, config=config, verifier=verifier)


class SADeactivateAdditionalPDN(DeactivateAdditionalPDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(SADeactivateAdditionalPDN, self).__init__(executor=executor, config=config, verifier=verifier)


class LTEDeactivateAdditionalPDN(DeactivateAdditionalPDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(LTEDeactivateAdditionalPDN, self).__init__(executor=executor, config=config, verifier=verifier)


class PetrusSADeactivateAdditionalPDN(DeactivateAdditionalPDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(PetrusSADeactivateAdditionalPDN, self).__init__(executor=executor, config=config, verifier=verifier)

    def _generate_command_sequence(self):
        aid = AIDStore().pop_aid(self._pdn_name)
        return [EAPNACT(self._executor, EAPNACT.PDPContextActivation.DEACTIVATED, aid)]


class PetrusNSADeactivateAdditionalPDN(DeactivateAdditionalPDN):

    def __init__(self, executor=None, config=None, verifier=None):
        super(PetrusNSADeactivateAdditionalPDN, self).__init__(executor=executor, config=config, verifier=verifier)

    def _generate_command_sequence(self):
        return []
